if(!EditorApplication.isPlaying)throw new Exception("Play gerekli.");
var source=UnityEngine.Object.FindFirstObjectByType<Corrigible.Desk.Bridge.MockRaidDataSource>();
var originalKeyboard=UnityEngine.InputSystem.Keyboard.current;var originalMouse=UnityEngine.InputSystem.Mouse.current;
var kb=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Keyboard>();var mouse=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Mouse>();kb.MakeCurrent();mouse.MakeCurrent();
bool settingsDirty=EditorUtility.IsDirty(UnityEngine.InputSystem.InputSystem.settings);var background=UnityEngine.InputSystem.InputSystem.settings.backgroundBehavior;UnityEngine.InputSystem.InputSystem.settings.backgroundBehavior=UnityEngine.InputSystem.InputSettings.BackgroundBehavior.IgnoreFocus;
var checks=new List<string>();var errors=new List<string>();var steps=new List<Action>();
void Check(bool value,string name){if(!value)throw new Exception(name);checks.Add(name);}
void Key(params UnityEngine.InputSystem.Key[] key){steps.Add(()=>UnityEngine.InputSystem.InputSystem.QueueStateEvent(kb,new UnityEngine.InputSystem.LowLevel.KeyboardState(key)));steps.Add(()=>UnityEngine.InputSystem.InputSystem.QueueStateEvent(kb,new UnityEngine.InputSystem.LowLevel.KeyboardState()));}
steps.Add(()=>source.LoadPreset(1));Key(UnityEngine.InputSystem.Key.L);steps.Add(()=>Check(source.Current.OpenPanel=="log","L günlük açar"));
Key(UnityEngine.InputSystem.Key.F1);steps.Add(()=>Check(source.Current.OpenPanel=="rules","F1 kuralları açar, günlüğü kapatır"));Key(UnityEngine.InputSystem.Key.Escape);steps.Add(()=>Check(source.Current.OpenPanel==null,"Esc paneli kapatır"));
Key(UnityEngine.InputSystem.Key.Enter);steps.Add(()=>Check(source.Current.EndConfirm,"Enter kullanılmayan hakları sorar"));Key(UnityEngine.InputSystem.Key.Escape);steps.Add(()=>Check(!source.Current.EndConfirm,"Esc tur onayını kaldırır"));
steps.Add(()=>source.LoadPreset(3));Key(UnityEngine.InputSystem.Key.Space);steps.Add(()=>Check(source.Current.FastMachines,"Boşluk makineleri hızlandırır"));Key(UnityEngine.InputSystem.Key.Digit1);steps.Add(()=>Check(source.Current.UnitCard==null,"Makineler sırasında 1 seçmez"));
steps.Add(()=>source.LoadPreset(8));Key(UnityEngine.InputSystem.Key.Escape);steps.Add(()=>Check(!source.Current.RetreatArmed,"Esc geri çekilmeyi iptal eder"));
steps.Add(()=>source.LoadPreset(9));Key(UnityEngine.InputSystem.Key.Enter);steps.Add(()=>Check(!source.Current.Finished&&source.State.Turn==3,"Sonuçta Enter rapor komutunu çalıştırır"));
var hud=UnityEngine.Object.FindFirstObjectByType<Corrigible.Desk.RaidHudView>();var hs=new SerializedObject(hud);var ps=new SerializedObject(UnityEngine.Object.FindFirstObjectByType<Corrigible.Desk.RaidPanelsView>());
void Click(SerializedObject refs,string field){Vector2 point=Vector2.zero;steps.Add(()=>{var button=(UnityEngine.UI.Button)refs.FindProperty(field).objectReferenceValue;var rect=(RectTransform)button.transform;point=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center));UnityEngine.InputSystem.InputSystem.QueueStateEvent(mouse,new UnityEngine.InputSystem.LowLevel.MouseState{position=point});});steps.Add(()=>UnityEngine.InputSystem.InputSystem.QueueStateEvent(mouse,new UnityEngine.InputSystem.LowLevel.MouseState{position=point}.WithButton(UnityEngine.InputSystem.LowLevel.MouseButton.Left)));steps.Add(()=>UnityEngine.InputSystem.InputSystem.QueueStateEvent(mouse,new UnityEngine.InputSystem.LowLevel.MouseState{position=point}));}
Click(hs,"rules");steps.Add(()=>Check(source.Current.OpenPanel=="rules","Fare Kurallar düğmesini açar"));Click(ps,"closeRules");steps.Add(()=>Check(source.Current.OpenPanel==null,"Fare Kurallar kapatır"));
Click(hs,"retreat");steps.Add(()=>Check(source.Current.RetreatArmed,"Fare geri çekilme ilk onayı"));Click(ps,"cancelRetreat");steps.Add(()=>Check(!source.Current.RetreatArmed,"Fare geri çekilmeyi iptal eder"));
Click(hs,"retreat");Click(ps,"retreatAgain");steps.Add(()=>Check(source.Current.Finished&&!source.Current.Success,"Yükseltilmiş düğme geri çeker"));Key(UnityEngine.InputSystem.Key.Enter);
Click(hs,"log");steps.Add(()=>Check(source.Current.OpenPanel=="log","Fare Günlük düğmesini açar"));Click(ps,"closeLog");steps.Add(()=>Check(source.Current.OpenPanel==null,"Fare Günlük kapatır"));
Key(UnityEngine.InputSystem.Key.LeftShift,UnityEngine.InputSystem.Key.F7);steps.Add(()=>Check(source.Current.LastTurn&&source.Current.OpenPanel==null,"Shift F7 son tur örneğini açar; F1 paneli karışmaz"));
Key(UnityEngine.InputSystem.Key.LeftShift,UnityEngine.InputSystem.Key.F1);steps.Add(()=>Check(source.Current.Turn==3&&source.Current.OpenPanel==null,"Shift F1 başlangıç örneğini açar; kuralları açmaz"));
Key(UnityEngine.InputSystem.Key.LeftCtrl,UnityEngine.InputSystem.Key.F1);steps.Add(()=>Check(source.Selected=='E'&&source.Armed,"Ctrl F1 B3 önizlemesini açar; kuralları açmaz"));
Key(UnityEngine.InputSystem.Key.LeftCtrl,UnityEngine.InputSystem.Key.F2);steps.Add(()=>Check(source.Selected=='\0'&&!source.Armed,"Ctrl F2 B4 örneğini açar"));
var lang=Corrigible.Desk.DeskLoc.Instance.Lang;Key(UnityEngine.InputSystem.Key.F10);steps.Add(()=>Check(Corrigible.Desk.DeskLoc.Instance.Lang!=lang,"F10 dili değiştirir"));
var reference=UnityEngine.Object.FindFirstObjectByType<Corrigible.Desk.ReferenceOverlay>();Key(UnityEngine.InputSystem.Key.F12);steps.Add(()=>Check(reference.GetComponent<UnityEngine.UI.RawImage>().enabled,"F12 referansı açar"));Key(UnityEngine.InputSystem.Key.F11);steps.Add(()=>Check(Mathf.Abs(reference.GetComponent<UnityEngine.UI.RawImage>().color.a-.75f)<.001f,"F11 opaklığı ilerletir"));Key(UnityEngine.InputSystem.Key.F12);steps.Add(()=>Check(!reference.GetComponent<UnityEngine.UI.RawImage>().enabled,"F12 referansı kapatır"));
int step=0;double next=EditorApplication.timeSinceStartup+.3;EditorApplication.CallbackFunction tick=null;
tick=()=>{if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.3;try{steps[step++]();}catch(Exception e){errors.Add(e.ToString());step=steps.Count;}if(step>=steps.Count){EditorApplication.update-=tick;UnityEngine.InputSystem.InputSystem.RemoveDevice(kb);UnityEngine.InputSystem.InputSystem.RemoveDevice(mouse);if(originalKeyboard!=null)originalKeyboard.MakeCurrent();if(originalMouse!=null)originalMouse.MakeCurrent();UnityEngine.InputSystem.InputSystem.settings.backgroundBehavior=background;if(!settingsDirty)EditorUtility.ClearDirty(UnityEngine.InputSystem.InputSystem.settings);System.IO.File.WriteAllText("Docs/UI_Sade/captures/F7/input_qa.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{passed=checks.Count,checks,errors,method="Unity Input System sanal klavye/fare; gerçek Update, EventSystem ve komut zinciri"},Newtonsoft.Json.Formatting.Indented));}};
EditorApplication.update+=tick;return new{started=true,steps=steps.Count};
